[FunctionName("ProcessEmailQueue")]
public async Task Run(
    [QueueTrigger("email-queue", Connection = "AzureWebJobsStorage")] string message,
    [Queue("email-deadletter", Connection = "AzureWebJobsStorage")] IAsyncCollector<string> deadLetter,
    ILogger log)
{
    try
    {
        await _emailService.SendAsync(message);
        log.LogInformation("Email sent: {Message}", message);
    }
    catch (Exception ex)
    {
        log.LogError(ex, "Failed to process email");
        await deadLetter.AddAsync(message);
    }
}
